#!/usr/bin/env bash
# Runs inside the target chroot. The ISO ships a build pacman.conf pinned to the
# Arch Linux Archive and pointing at a local repo; the installed system must get a
# normal configuration with live mirrors and [multilib] (Steam/Proton).
set -euo pipefail

export LC_ALL=C

MIRRORLIST=/etc/pacman.d/mirrorlist

echo ":: [mahadevanos] writing mirrorlist"
cat >"$MIRRORLIST" <<'EOF'
##
## Arch Linux repository mirrorlist
## Generated by MahaDevan's OS post-install. Rank with reflector if you prefer.
##
Server = https://geo.mirror.pkgbuild.com/$repo/os/$arch
Server = https://mirror.rackspace.com/archlinux/$repo/os/$arch
Server = https://mirrors.kernel.org/archlinux/$repo/os/$arch
EOF

# Write a complete, known-good pacman.conf rather than patching the pinned build
# one: no archive URL, no mahadevanos-local, multilib enabled.
echo ":: [mahadevanos] writing /etc/pacman.conf"
cat >/etc/pacman.conf <<'EOF'
#
# /etc/pacman.conf — MahaDevan's OS
#
[options]
HoldPkg     = pacman glibc
Architecture = auto
Color
CheckSpace
ParallelDownloads = 5
SigLevel    = Required DatabaseOptional
LocalFileSigLevel = Optional

[core]
Include = /etc/pacman.d/mirrorlist

[extra]
Include = /etc/pacman.d/mirrorlist

[multilib]
Include = /etc/pacman.d/mirrorlist
EOF

# Rank mirrors when reflector is available; never fatal, the install is offline-capable.
if command -v reflector >/dev/null 2>&1; then
  reflector --latest 20 --protocol https --sort rate --save "$MIRRORLIST" || true
fi

# Refresh sync databases now, while the install media is still mounted.
pacman -Sy --noconfirm || true

echo ":: [mahadevanos] mirrors and pacman.conf updated"
